export const aboutBaselineHtml = "<!-- ===================== ABOUT US — SECTION 1 (HERO – CLEAN) ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:   #020C4F;\r\n    --c-indigo: #313B86;\r\n    --c-violet: #625AD8;\r\n    --c-pink:   #FF4B8C;\r\n    --white:    #FFFFFF;\r\n\r\n    --heroText: rgba(255,255,255,0.96);\r\n    --heroTextSoft: rgba(240,244,255,0.88);\r\n  }\r\n\r\n  html,body{margin:0;padding:0;font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;}\r\n\r\n  /* HERO */\r\n  .about-hero{\r\n    position:relative;\r\n    min-height:78vh;\r\n    display:flex;\r\n    align-items:center;\r\n    color:var(--white);\r\n    background:\r\n      url('https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/marc-olivier-jodoin-K9GMQEETUAw-unsplash-scaled.jpg')\r\n      center/cover no-repeat;\r\n    overflow:hidden;\r\n    isolation:isolate;\r\n  }\r\n\r\n  /* light mesh overlay (NOT blocking image) */\r\n  .about-hero::before{\r\n    content:\"\";\r\n    position:absolute;\r\n    inset:0;\r\n    z-index:0;\r\n    pointer-events:none;\r\n    background:\r\n      radial-gradient(900px 520px at 18% 40%, rgba(255,120,191,0.18), transparent 60%),\r\n      radial-gradient(900px 520px at 75% 30%, rgba(98,90,216,0.18), transparent 58%),\r\n      linear-gradient(115deg,\r\n        rgba(2,12,79,0.55) 0%,\r\n        rgba(49,59,134,0.38) 45%,\r\n        rgba(98,90,216,0.26) 70%,\r\n        rgba(255,75,140,0.12) 100%\r\n      );\r\n  }\r\n\r\n  /* subtle premium wave texture */\r\n  .about-hero::after{\r\n    content:\"\";\r\n    position:absolute;\r\n    inset:-40px;\r\n    z-index:0;\r\n    pointer-events:none;\r\n    opacity:0.22;\r\n    background:\r\n      repeating-radial-gradient(\r\n        circle at 0% 25%,\r\n        rgba(255,255,255,0.18) 0px,\r\n        rgba(255,255,255,0.18) 1px,\r\n        transparent 1px,\r\n        transparent 36px\r\n      );\r\n    transform:rotate(-6deg);\r\n    mix-blend-mode:overlay;\r\n  }\r\n\r\n  .about-hero__inner{\r\n    position:relative;\r\n    z-index:1;\r\n    width:100%;\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n    padding:110px 20px 90px;\r\n  }\r\n\r\n  .about-hero__eyebrow{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:8px 14px;\r\n    border-radius:999px;\r\n    border:1px solid rgba(255,255,255,0.28);\r\n    background:rgba(255,255,255,0.08);\r\n    backdrop-filter: blur(8px);\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    margin-bottom:18px;\r\n  }\r\n\r\n  .about-hero__dot{\r\n    width:8px;height:8px;border-radius:99px;\r\n    background:linear-gradient(135deg,var(--c-pink),var(--c-violet));\r\n    box-shadow:0 0 0 6px rgba(255,75,140,0.14);\r\n  }\r\n\r\n  .about-hero__title{\r\n    max-width:820px;\r\n    margin:0 0 18px;\r\n    font-weight:700;\r\n    line-height:1.06;\r\n    font-size:clamp(36px,4.8vw,60px);\r\n    color:var(--heroText);\r\n    text-shadow:0 18px 38px rgba(0,0,0,0.35);\r\n  }\r\n\r\n  .about-hero__subtitle{\r\n    max-width:760px;\r\n    font-size:clamp(16px,1.9vw,20px);\r\n    line-height:1.65;\r\n    color:var(--heroTextSoft);\r\n  }\r\n\r\n  .about-hero__ctaRow{\r\n    margin-top:32px;\r\n    display:flex;\r\n    flex-wrap:wrap;\r\n    gap:14px;\r\n  }\r\n\r\n  .btn{\r\n    height:50px;\r\n    padding:0 24px;\r\n    border-radius:999px;\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    text-decoration:none;\r\n    font-weight:600;\r\n    font-size:14px;\r\n    transition:.22s ease;\r\n    white-space:nowrap;\r\n  }\r\n\r\n  .btn--primary{\r\n    background:var(--c-pink);\r\n    color:#fff;\r\n    box-shadow:0 18px 36px rgba(0,0,0,0.35);\r\n  }\r\n  .btn--primary:hover{\r\n    transform:translateY(-1px);\r\n    box-shadow:0 22px 44px rgba(0,0,0,0.45);\r\n    background:#E53A7A;\r\n  }\r\n\r\n  .btn--ghost{\r\n    background:rgba(255,255,255,0.08);\r\n    color:#fff;\r\n    border:1px solid rgba(255,255,255,0.35);\r\n    backdrop-filter: blur(10px);\r\n  }\r\n  .btn--ghost:hover{\r\n    background:rgba(255,255,255,0.12);\r\n    transform:translateY(-1px);\r\n  }\r\n\r\n  .reveal{\r\n    opacity:0;\r\n    transform:translateY(16px);\r\n    transition:opacity .7s ease, transform .7s ease;\r\n  }\r\n  .reveal.is-in{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n\r\n  @media (max-width:900px){\r\n    .about-hero__inner{\r\n      padding:95px 18px 80px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"about-hero\" id=\"about-hero\">\r\n  <div class=\"about-hero__inner reveal\">\r\n    <div class=\"about-hero__eyebrow\">\r\n      <span class=\"about-hero__dot\"></span>\r\n      About Us\r\n    </div>\r\n\r\n    <h1 class=\"about-hero__title\">\r\n      A new-age consulting firm redefining growth, efficiency, and impact\r\n    </h1>\r\n\r\n    <p class=\"about-hero__subtitle\">\r\n      We partner with leadership teams to translate strategy into execution — aligning people,\r\n      processes, and technology to deliver measurable, lasting business outcomes.\r\n    </p>\r\n\r\n    <div class=\"about-hero__ctaRow\">\r\n      <a href=\"#contact\" class=\"btn btn--primary\">Talk to Us →</a>\r\n      <a href=\"#who-we-are\" class=\"btn btn--ghost\">Who We Are ↓</a>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  // simple entrance animation\r\n  window.addEventListener('load', ()=>{\r\n    document.querySelector('.reveal')?.classList.add('is-in');\r\n  });\r\n</script>\r\n\r\n<!-- ===================== ABOUT US — SECTION 2 (CLEAN, NO BACKGROUND) ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:   #020C4F;\r\n    --c-indigo: #313B86;\r\n    --c-violet: #625AD8;\r\n    --c-pink:   #FF4B8C;\r\n    --black:    #0B0F1A;\r\n    --gray:     #5A5F78;\r\n    --line:     rgba(49,59,134,0.15);\r\n    --white:    #FFFFFF;\r\n  }\r\n\r\n  body{\r\n    margin:0;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:#fff;\r\n    color:var(--black);\r\n  }\r\n\r\n  /* SECTION */\r\n  .ab-clean{\r\n    padding:90px 20px;\r\n    background:#fff;\r\n  }\r\n\r\n  .ab-clean__inner{\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n    display:grid;\r\n    grid-template-columns:minmax(0,1.05fr) minmax(0,0.95fr);\r\n    gap:48px;\r\n    align-items:start;\r\n  }\r\n\r\n  /* LEFT */\r\n  .ab-clean__eyebrow{\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    margin-bottom:12px;\r\n    font-weight:600;\r\n  }\r\n\r\n  .ab-clean__title{\r\n    font-size:clamp(28px,3.4vw,40px);\r\n    line-height:1.15;\r\n    font-weight:700;\r\n    margin:0 0 14px;\r\n    color:var(--c-navy);\r\n  }\r\n\r\n  .ab-clean__intro{\r\n    font-size:16px;\r\n    line-height:1.7;\r\n    color:var(--gray);\r\n    max-width:720px;\r\n    margin-bottom:28px;\r\n  }\r\n\r\n  .ab-clean__cards{\r\n    display:grid;\r\n    grid-template-columns:1fr 1fr;\r\n    gap:20px;\r\n  }\r\n\r\n  .ab-card{\r\n    border:1px solid var(--line);\r\n    border-radius:16px;\r\n    padding:22px 22px 20px;\r\n    transition:transform .25s ease, box-shadow .25s ease;\r\n    background:#fff;\r\n  }\r\n\r\n  .ab-card:hover{\r\n    transform:translateY(-2px);\r\n    box-shadow:0 12px 28px rgba(0,0,0,0.06);\r\n  }\r\n\r\n  .ab-card__label{\r\n    font-size:12px;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:600;\r\n    margin-bottom:8px;\r\n  }\r\n\r\n  .ab-card__text{\r\n    font-size:14.5px;\r\n    line-height:1.7;\r\n    color:#2E334D;\r\n    margin:0;\r\n  }\r\n\r\n  /* RIGHT */\r\n  .ab-right{\r\n    border-left:2px solid var(--line);\r\n    padding-left:36px;\r\n  }\r\n\r\n  .ab-block{\r\n    margin-bottom:28px;\r\n  }\r\n\r\n  .ab-block__label{\r\n    font-size:12px;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:600;\r\n    margin-bottom:8px;\r\n  }\r\n\r\n  .ab-block__highlight{\r\n    font-size:20px;\r\n    font-weight:700;\r\n    line-height:1.4;\r\n    color:var(--c-navy);\r\n    margin-bottom:12px;\r\n  }\r\n\r\n  .ab-block__text{\r\n    font-size:15px;\r\n    line-height:1.7;\r\n    color:#3C4160;\r\n    margin:0;\r\n  }\r\n\r\n  .ab-core{\r\n    padding-top:18px;\r\n    border-top:1px solid var(--line);\r\n  }\r\n\r\n  /* CTA */\r\n  .ab-clean__cta{\r\n    margin-top:30px;\r\n    display:flex;\r\n    gap:14px;\r\n    flex-wrap:wrap;\r\n  }\r\n\r\n  .ab-btn{\r\n    height:46px;\r\n    padding:0 22px;\r\n    border-radius:999px;\r\n    display:inline-flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    font-size:14px;\r\n    font-weight:600;\r\n    text-decoration:none;\r\n    transition:.22s ease;\r\n    white-space:nowrap;\r\n  }\r\n\r\n  .ab-btn--primary{\r\n    background:var(--c-pink);\r\n    color:#fff;\r\n  }\r\n  .ab-btn--primary:hover{\r\n    background:#E53A7A;\r\n    transform:translateY(-1px);\r\n  }\r\n\r\n  .ab-btn--ghost{\r\n    border:1px solid var(--line);\r\n    color:var(--c-navy);\r\n    background:#fff;\r\n  }\r\n  .ab-btn--ghost:hover{\r\n    background:#F6F7FB;\r\n    transform:translateY(-1px);\r\n  }\r\n\r\n  /* ANIMATION */\r\n  .ab-reveal{\r\n    opacity:0;\r\n    transform:translateY(14px);\r\n    transition:opacity .7s ease, transform .7s ease;\r\n  }\r\n  .ab-reveal.is-in{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n\r\n  @media (max-width:980px){\r\n    .ab-clean__inner{\r\n      grid-template-columns:1fr;\r\n      gap:36px;\r\n    }\r\n    .ab-right{\r\n      border-left:none;\r\n      padding-left:0;\r\n      border-top:2px solid var(--line);\r\n      padding-top:30px;\r\n    }\r\n    .ab-clean__cards{\r\n      grid-template-columns:1fr;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"ab-clean\" id=\"purpose-vision\">\r\n  <div class=\"ab-clean__inner\">\r\n\r\n    <!-- LEFT -->\r\n    <div class=\"ab-reveal\">\r\n      <div class=\"ab-clean__eyebrow\">Purpose &amp; Vision</div>\r\n      <h2 class=\"ab-clean__title\">What we stand for — and where we’re going</h2>\r\n      <p class=\"ab-clean__intro\">\r\n        Our consulting philosophy is grounded in one belief: lasting transformation happens\r\n        when strategy, execution, and people move together.\r\n      </p>\r\n\r\n      <div class=\"ab-clean__cards\">\r\n        <div class=\"ab-card\">\r\n          <div class=\"ab-card__label\">Vision</div>\r\n          <p class=\"ab-card__text\">\r\n            To be the consulting partner known for turning every client investment into a multiplier\r\n            of growth, innovation, and lasting impact — powered by a team that thrives on making a difference.\r\n          </p>\r\n        </div>\r\n\r\n        <div class=\"ab-card\">\r\n          <div class=\"ab-card__label\">Purpose</div>\r\n          <p class=\"ab-card__text\">\r\n            To transform businesses in ways that transform lives — enabling our clients,\r\n            their customers, and our own people to achieve more than they imagined possible.\r\n          </p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- RIGHT -->\r\n    <div class=\"ab-right ab-reveal\">\r\n      <div class=\"ab-block\">\r\n        <div class=\"ab-block__label\">Tagline</div>\r\n        <div class=\"ab-block__highlight\">\r\n          Where revenue growth meets operational excellence and meaningful impact.\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"ab-block\">\r\n        <div class=\"ab-block__label\">Brand Promise</div>\r\n        <p class=\"ab-block__text\">\r\n          We help organizations grow faster, operate smarter, and create lasting value — for their\r\n          customers, employees, and stakeholders — turning every consulting dollar into a multiplier\r\n          of measurable results.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-block ab-core\">\r\n        <div class=\"ab-block__label\">Core Belief</div>\r\n        <p class=\"ab-block__text\">\r\n          Transformation works best when strategy meets execution — and when people are at the heart of change.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-clean__cta\">\r\n        <a href=\"#contact\" class=\"ab-btn ab-btn--primary\">Talk to Us →</a>\r\n        <a href=\"#who-we-are\" class=\"ab-btn ab-btn--ghost\">Next: Who We Are ↓</a>\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  (function(){\r\n    function initAboutReveal(scope){\r\n      // scope = elementor widget/container, or document\r\n      const root = scope && scope.querySelector ? scope : document;\r\n      const section = root.querySelector('#purpose-vision');\r\n      if(!section) return;\r\n\r\n      // prevent double-init\r\n      if(section.dataset.abInit === \"1\") return;\r\n      section.dataset.abInit = \"1\";\r\n\r\n      const items = section.querySelectorAll('.ab-reveal');\r\n      items.forEach((el,i)=>{\r\n        setTimeout(()=> el.classList.add('is-in'), i*120);\r\n      });\r\n    }\r\n\r\n    // Works on normal pages\r\n    document.addEventListener('DOMContentLoaded', function(){\r\n      initAboutReveal(document);\r\n    });\r\n\r\n    // Works inside Elementor editor + frontend renders\r\n    if(window.elementorFrontend && window.elementorFrontend.hooks){\r\n      window.elementorFrontend.hooks.addAction('frontend/element_ready/global', function($scope){\r\n        // $scope is a jQuery object in Elementor; convert safely\r\n        const el = $scope && $scope[0] ? $scope[0] : document;\r\n        initAboutReveal(el);\r\n      });\r\n    }\r\n  })();\r\n</script>\r\n\r\n<!-- ===================== ABOUT US — ORIGIN STORY (MATCHING YOUR SCREENSHOT) ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:   #020C4F;\r\n    --c-indigo: #313B86;\r\n    --c-violet: #625AD8;\r\n    --c-pink:   #FF4B8C;\r\n\r\n    --black: #0B0F1A;\r\n    --gray:  #4B5168;\r\n    --muted: #2E334D;\r\n    --line:  rgba(49,59,134,0.18);\r\n    --pill:  rgba(2,12,79,0.06);\r\n    --white: #FFFFFF;\r\n  }\r\n\r\n  .ab-origin2, .ab-origin2 *{ box-sizing:border-box; }\r\n\r\n  .ab-origin2{\r\n    padding:90px 20px;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    color:var(--black);\r\n\r\n    /* ✅ PREMIUM EXECUTIVE BACKGROUND */\r\n    background:\r\n      radial-gradient(circle at 12% 0%, rgba(98,90,216,.08), transparent 55%),\r\n      radial-gradient(circle at 92% 28%, rgba(49,59,134,.08), transparent 55%),\r\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\r\n      rgba(49,59,134,.03);\r\n  }\r\n\r\n  .ab-origin2__inner{\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n    display:grid;\r\n    grid-template-columns:minmax(0,1.1fr) minmax(0,0.9fr);\r\n    gap:56px;\r\n    align-items:start;\r\n  }\r\n\r\n  /* LEFT */\r\n  .ab-origin2__kicker{\r\n    font-size:12px;\r\n    letter-spacing:.22em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:700;\r\n    margin-bottom:14px;\r\n  }\r\n\r\n  .ab-origin2__title{\r\n    margin:0 0 18px;\r\n    font-size:clamp(34px,4vw,52px);\r\n    line-height:1.06;\r\n    font-weight:800;\r\n    color:var(--c-navy);\r\n  }\r\n\r\n  .ab-origin2__lead{\r\n    margin:0 0 18px;\r\n    font-size:16px;\r\n    line-height:1.9;\r\n    color:var(--gray);\r\n    max-width:760px;\r\n    white-space:normal;\r\n    overflow-wrap:anywhere;\r\n  }\r\n\r\n  .ab-origin2__lead b{\r\n    color:var(--black);\r\n    font-weight:700;\r\n  }\r\n\r\n  /* RIGHT */\r\n  .ab-origin2__right{\r\n    border-left:2px solid var(--line);\r\n    padding-left:42px;\r\n    min-width:0;\r\n    width:100%;\r\n  }\r\n\r\n  .ab-origin2__stack{\r\n    display:grid;\r\n    gap:18px;\r\n    min-width:0;\r\n  }\r\n\r\n  .ab-origin2__card{\r\n    border:1px solid var(--line);\r\n    border-radius:18px;\r\n    background:#fff;\r\n    padding:18px 18px 16px;\r\n    transition:transform .22s ease, box-shadow .22s ease, border-color .22s ease;\r\n    min-width:0;\r\n  }\r\n\r\n  .ab-origin2__card:hover{\r\n    transform:translateY(-2px);\r\n    box-shadow:0 14px 34px rgba(0,0,0,0.06);\r\n    border-color:rgba(98,90,216,0.28);\r\n  }\r\n\r\n  /* CARD HEADER */\r\n  .ab-origin2__head{\r\n    display:flex;\r\n    align-items:center;\r\n    gap:14px;\r\n    margin-bottom:10px;\r\n    min-width:0;\r\n  }\r\n\r\n  .ab-origin2__num{\r\n    flex:0 0 auto;\r\n    height:34px;\r\n    padding:0 12px;\r\n    border-radius:999px;\r\n    display:inline-flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    border:1px solid var(--line);\r\n    background:var(--pill);\r\n    color:var(--c-navy);\r\n    font-weight:800;\r\n    font-size:13px;\r\n    letter-spacing:.02em;\r\n  }\r\n\r\n  .ab-origin2__h{\r\n    margin:0;\r\n    font-size:13px;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    font-weight:800;\r\n    color:var(--c-navy);\r\n    line-height:1.25;\r\n    min-width:0;\r\n    white-space:normal;\r\n    overflow-wrap:anywhere;\r\n  }\r\n\r\n  .ab-origin2__text{\r\n    margin:0;\r\n    font-size:14.5px;\r\n    line-height:1.75;\r\n    color:var(--muted);\r\n    min-width:0;\r\n    width:100%;\r\n    white-space:normal;\r\n    overflow-wrap:anywhere;\r\n  }\r\n\r\n  /* reveal */\r\n  .ab-reveal{opacity:0; transform:translateY(14px); transition:opacity .75s ease, transform .75s ease;}\r\n  .ab-reveal.is-in{opacity:1; transform:translateY(0);}\r\n\r\n  @media (max-width:980px){\r\n    .ab-origin2__inner{grid-template-columns:1fr; gap:34px;}\r\n    .ab-origin2__right{\r\n      border-left:none;\r\n      padding-left:0;\r\n      border-top:2px solid var(--line);\r\n      padding-top:26px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"ab-origin2\" id=\"origin\">\r\n  <div class=\"ab-origin2__inner\">\r\n\r\n    <!-- LEFT -->\r\n    <div class=\"ab-reveal\">\r\n      <div class=\"ab-origin2__kicker\">ORIGIN STORY</div>\r\n      <h2 class=\"ab-origin2__title\">Built to deliver sustainable results</h2>\r\n\r\n      <p class=\"ab-origin2__lead\">\r\n        It all began with a bold question:\r\n        <b>How can we work hand in hand with our clients to deliver sustainable results</b>—where every consulting dollar becomes a multiplier of growth, innovation, and impact?\r\n      </p>\r\n\r\n      <p class=\"ab-origin2__lead\">\r\n        Our answer was to create a model that fuses deep expertise with technology, and a delivery approach that scales globally while staying personal.\r\n      </p>\r\n    </div>\r\n\r\n    <!-- RIGHT -->\r\n    <div class=\"ab-origin2__right ab-reveal\">\r\n      <div class=\"ab-origin2__stack\">\r\n\r\n        <article class=\"ab-origin2__card\">\r\n          <div class=\"ab-origin2__head\">\r\n            <div class=\"ab-origin2__num\">01</div>\r\n            <h3 class=\"ab-origin2__h\">HAND-IN-HAND DELIVERY</h3>\r\n          </div>\r\n          <p class=\"ab-origin2__text\">\r\n            We work as an extension of your leadership team — co-owning the problem, the plan, and the outcome.\r\n          </p>\r\n        </article>\r\n\r\n        <article class=\"ab-origin2__card\">\r\n          <div class=\"ab-origin2__head\">\r\n            <div class=\"ab-origin2__num\">02</div>\r\n            <h3 class=\"ab-origin2__h\">DEEP EXPERTISE × TECH</h3>\r\n          </div>\r\n          <p class=\"ab-origin2__text\">\r\n            A model that fuses domain expertise with technology so execution is faster, smarter, and scalable.\r\n          </p>\r\n        </article>\r\n\r\n        <article class=\"ab-origin2__card\">\r\n          <div class=\"ab-origin2__head\">\r\n            <div class=\"ab-origin2__num\">03</div>\r\n            <h3 class=\"ab-origin2__h\">GLOBAL SCALE, PERSONAL FEEL</h3>\r\n          </div>\r\n          <p class=\"ab-origin2__text\">\r\n            A globally scalable delivery approach that stays personal — ensuring clarity, continuity, and trust.\r\n          </p>\r\n        </article>\r\n\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  window.addEventListener('load', () => {\r\n    document.querySelectorAll('.ab-reveal').forEach((el,i)=>{\r\n      setTimeout(()=> el.classList.add('is-in'), i*140);\r\n    });\r\n  });\r\n</script>\r\n\r\n<!-- ===================== ABOUT US — VISION • PROGRESS MILESTONE • TEAM CULTURE (WITH VISUALS, NO BG) ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:   #020C4F;\r\n    --c-indigo: #313B86;\r\n    --c-violet: #625AD8;\r\n    --c-pink:   #FF4B8C;\r\n\r\n    --black:#0B0F1A;\r\n    --gray:#4B5168;\r\n    --line:rgba(49,59,134,0.16);\r\n    --white:#FFFFFF;\r\n  }\r\n\r\n  .ab-vmtc, .ab-vmtc *{ box-sizing:border-box; }\r\n\r\n  .ab-vmtc{\r\n    padding:90px 20px;\r\n    background:#fff;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    color:var(--black);\r\n  }\r\n  .ab-vmtc__inner{max-width:1200px;margin:0 auto;}\r\n\r\n  .ab-vmtc__head{\r\n    display:flex;align-items:flex-end;justify-content:space-between;gap:18px;\r\n    margin-bottom:22px;\r\n  }\r\n  .ab-vmtc__kicker{\r\n    font-size:12px;letter-spacing:.22em;text-transform:uppercase;\r\n    color:var(--c-indigo);font-weight:800;margin:0 0 10px;\r\n  }\r\n  .ab-vmtc__title{\r\n    margin:0;font-size:clamp(26px,3vw,36px);line-height:1.15;\r\n    font-weight:800;color:var(--c-navy);\r\n  }\r\n  .ab-vmtc__rule{\r\n    height:2px;width:220px;border-radius:999px;\r\n    background:linear-gradient(90deg,var(--c-navy),var(--c-indigo),var(--c-violet),var(--c-pink));\r\n    opacity:.9;margin-bottom:6px;flex:0 0 auto;\r\n  }\r\n\r\n  .ab-vmtc__grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;}\r\n\r\n  .ab-vmtc__card{\r\n    position:relative;border:1px solid var(--line);border-radius:18px;\r\n    padding:22px 22px 20px;background:#fff;overflow:hidden;\r\n    transition:transform .25s ease, box-shadow .25s ease, border-color .25s ease;\r\n  }\r\n  .ab-vmtc__card::before{\r\n    content:\"\";position:absolute;left:0;top:0;height:4px;width:100%;\r\n    background:linear-gradient(90deg,var(--c-indigo),var(--c-violet),var(--c-pink));\r\n  }\r\n  .ab-vmtc__card:hover{\r\n    transform:translateY(-2px);\r\n    box-shadow:0 14px 34px rgba(0,0,0,0.06);\r\n    border-color:rgba(98,90,216,0.26);\r\n  }\r\n\r\n  .ab-vmtc__label{display:flex;align-items:center;gap:10px;margin:0 0 10px;}\r\n  .ab-vmtc__icon{\r\n    width:40px;height:40px;border-radius:14px;display:grid;place-items:center;\r\n    background:rgba(2,12,79,0.05);\r\n    border:1px solid rgba(49,59,134,0.18);\r\n    color:var(--c-indigo);flex:0 0 auto;\r\n  }\r\n  .ab-vmtc__labeltext{\r\n    font-size:12px;letter-spacing:.16em;text-transform:uppercase;\r\n    color:var(--c-indigo);font-weight:800;margin:0;line-height:1.2;\r\n  }\r\n  .ab-vmtc__text{margin:0;font-size:15px;line-height:1.8;color:var(--gray);}\r\n\r\n  /* reveal */\r\n  .ab-reveal{opacity:0;transform:translateY(14px);transition:opacity .75s ease, transform .75s ease;}\r\n  .ab-reveal.is-in{opacity:1;transform:translateY(0);}\r\n\r\n  /* ✅ Elementor editor: always show (JS may not run) */\r\n  .elementor-editor-active .ab-reveal,\r\n  .elementor-editor-preview .ab-reveal,\r\n  body.elementor-editor-active .ab-reveal,\r\n  body.elementor-editor-preview .ab-reveal{\r\n    opacity:1 !important;\r\n    transform:none !important;\r\n  }\r\n\r\n  @media (max-width:980px){\r\n    .ab-vmtc{padding:74px 18px;}\r\n    .ab-vmtc__head{flex-direction:column;align-items:flex-start;}\r\n    .ab-vmtc__rule{width:160px;}\r\n    .ab-vmtc__grid{grid-template-columns:1fr;gap:14px;}\r\n  }\r\n</style>\r\n\r\n<section class=\"ab-vmtc\" id=\"vision-milestone-culture\">\r\n  <div class=\"ab-vmtc__inner\">\r\n\r\n    <div class=\"ab-vmtc__head ab-reveal\">\r\n      <div>\r\n        <p class=\"ab-vmtc__kicker\">FOUNDATION</p>\r\n        <h2 class=\"ab-vmtc__title\">Vision, progress, and culture</h2>\r\n      </div>\r\n      <div class=\"ab-vmtc__rule\" aria-hidden=\"true\"></div>\r\n    </div>\r\n\r\n    <div class=\"ab-vmtc__grid\">\r\n\r\n      <article class=\"ab-vmtc__card ab-reveal\">\r\n        <div class=\"ab-vmtc__label\">\r\n          <div class=\"ab-vmtc__icon\" aria-hidden=\"true\">\r\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\">\r\n              <path d=\"M2.2 12s3.6-7 9.8-7 9.8 7 9.8 7-3.6 7-9.8 7S2.2 12 2.2 12Z\" stroke=\"currentColor\" stroke-width=\"2\" />\r\n              <path d=\"M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z\" stroke=\"currentColor\" stroke-width=\"2\" />\r\n            </svg>\r\n          </div>\r\n          <p class=\"ab-vmtc__labeltext\">Vision</p>\r\n        </div>\r\n        <p class=\"ab-vmtc__text\">\r\n          To be the consulting partner known for turning every client investment into a multiplier of growth,\r\n          innovation, and lasting impact — powered by a team that thrives on making a difference.\r\n        </p>\r\n      </article>\r\n\r\n      <article class=\"ab-vmtc__card ab-reveal\">\r\n        <div class=\"ab-vmtc__label\">\r\n          <div class=\"ab-vmtc__icon\" aria-hidden=\"true\">\r\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\">\r\n              <path d=\"M14 4c3.8 1 6 4.3 6 8.2 0 2.7-1.1 5.3-3 7.2l-4.3-4.3\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n              <path d=\"M10 20c-3.8-1-6-4.3-6-8.2 0-2.7 1.1-5.3 3-7.2l4.3 4.3\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n              <path d=\"M9.5 14.5 14.5 9.5\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n            </svg>\r\n          </div>\r\n          <p class=\"ab-vmtc__labeltext\">Progress Milestone</p>\r\n        </div>\r\n        <p class=\"ab-vmtc__text\">\r\n          In a short span, we’ve brought together exceptional global talent, industry-leading expertise, and a\r\n          tech-enabled, integrated delivery model to help organizations achieve measurable results and enduring transformation.\r\n        </p>\r\n      </article>\r\n\r\n      <article class=\"ab-vmtc__card ab-reveal\">\r\n        <div class=\"ab-vmtc__label\">\r\n          <div class=\"ab-vmtc__icon\" aria-hidden=\"true\">\r\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\">\r\n              <path d=\"M16 11a3 3 0 1 0-6 0 3 3 0 0 0 6 0Z\" stroke=\"currentColor\" stroke-width=\"2\"/>\r\n              <path d=\"M3 20c1.5-3 4.3-5 8-5s6.5 2 8 5\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n              <path d=\"M20 20c-.6-1.2-1.5-2.3-2.6-3.1\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n              <path d=\"M6.6 16.9C5.5 17.7 4.6 18.8 4 20\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>\r\n            </svg>\r\n          </div>\r\n          <p class=\"ab-vmtc__labeltext\">Team Culture</p>\r\n        </div>\r\n        <p class=\"ab-vmtc__text\">\r\n          Our team is united by a shared purpose, fueled by agility, and thrives on collaboration. We build trust through\r\n          integrity, deliver excellence through discipline, and measure success by the lasting impact we create for our clients,\r\n          their customers, and stakeholders.\r\n        </p>\r\n      </article>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  // Run immediately + on Elementor frontend init (covers editor quirks)\r\n  (function(){\r\n    function revealNow(){\r\n      document.querySelectorAll('#vision-milestone-culture .ab-reveal').forEach((el,i)=>{\r\n        setTimeout(()=> el.classList.add('is-in'), i*130);\r\n      });\r\n    }\r\n    if (document.readyState === 'complete' || document.readyState === 'interactive') {\r\n      revealNow();\r\n    } else {\r\n      document.addEventListener('DOMContentLoaded', revealNow);\r\n    }\r\n    window.addEventListener('load', revealNow);\r\n  })();\r\n</script>\r\n\r\n<!-- ===================== ABOUT US — CORE SERVICES & ENABLERS ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:#020C4F;\r\n    --c-indigo:#313B86;\r\n    --c-violet:#625AD8;\r\n    --c-pink:#FF4B8C;\r\n\r\n    --black:#0B0F1A;\r\n    --gray:#4B5168;\r\n    --line:rgba(49,59,134,0.16);\r\n    --soft:rgba(2,12,79,0.04);\r\n    --white:#FFFFFF;\r\n  }\r\n\r\n  body{\r\n    margin:0;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:#fff;\r\n    color:var(--black);\r\n  }\r\n\r\n  /* SECTION */\r\n  .ab-services{\r\n    padding:96px 20px;\r\n\r\n    /* ✅ PREMIUM EXECUTIVE BACKGROUND (MATCHES OTHER SECTIONS) */\r\n    background:      radial-gradient(circle at 14% 0%, rgba(98,90,216,.08), transparent 55%),\r\n      radial-gradient(circle at 92% 28%, rgba(49,59,134,.08), transparent 55%),\r\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\r\n      rgba(49,59,134,.03);\r\n\r\n  }\r\n\r\n  .ab-services__inner{\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n  }\r\n\r\n  /* HEADER */\r\n  .ab-services__eyebrow{\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:600;\r\n    margin-bottom:10px;\r\n  }\r\n\r\n  .ab-services__title{\r\n    font-size:clamp(30px,3.6vw,44px);\r\n    font-weight:700;\r\n    line-height:1.15;\r\n    color:var(--c-navy);\r\n    margin:0 0 22px;\r\n  }\r\n\r\n  .ab-services__intro{\r\n    font-size:16px;\r\n    line-height:1.75;\r\n    color:var(--gray);\r\n    max-width:900px;\r\n    margin-bottom:40px;\r\n  }\r\n\r\n  /* SERVICES GRID */\r\n  .ab-services__grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(2,minmax(0,1fr));\r\n    gap:26px 40px;\r\n    margin-bottom:48px;\r\n  }\r\n\r\n  .ab-service{\r\n    padding-left:18px;\r\n    border-left:3px solid var(--line);\r\n    transition:border-color .25s ease, transform .25s ease;\r\n  }\r\n\r\n  .ab-service:hover{\r\n    border-color:var(--c-violet);\r\n    transform:translateY(-2px);\r\n  }\r\n\r\n  .ab-service__title{\r\n    font-size:16px;\r\n    font-weight:600;\r\n    color:var(--c-navy);\r\n    margin:0 0 6px;\r\n  }\r\n\r\n  .ab-service__text{\r\n    margin:0;\r\n    font-size:14.5px;\r\n    line-height:1.7;\r\n    color:#2E334D;\r\n  }\r\n\r\n  /* ENABLERS */\r\n  .ab-enablers{\r\n    border-top:1px solid var(--line);\r\n    padding-top:32px;\r\n    display:grid;\r\n    grid-template-columns:minmax(0,0.4fr) minmax(0,0.6fr);\r\n    gap:40px;\r\n    align-items:start;\r\n  }\r\n\r\n  .ab-enablers__label{\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:700;\r\n  }\r\n\r\n  .ab-enablers__text{\r\n    font-size:15px;\r\n    line-height:1.75;\r\n    color:#3C4160;\r\n  }\r\n\r\n  /* REVEAL */\r\n  .ab-reveal{\r\n    opacity:0;\r\n    transform:translateY(14px);\r\n    transition:opacity .7s ease, transform .7s ease;\r\n  }\r\n  .ab-reveal.is-in{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n\r\n  @media (max-width:980px){\r\n    .ab-services{\r\n      padding:78px 18px;\r\n    }\r\n    .ab-services__grid{\r\n      grid-template-columns:1fr;\r\n      gap:22px;\r\n    }\r\n    .ab-enablers{\r\n      grid-template-columns:1fr;\r\n      gap:18px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"ab-services\" id=\"core-services\">\r\n  <div class=\"ab-services__inner\">\r\n\r\n    <div class=\"ab-reveal\">\r\n      <div class=\"ab-services__eyebrow\">Core Services</div>\r\n      <h2 class=\"ab-services__title\">What We Do — And How We Create Impact</h2>\r\n\r\n      <p class=\"ab-services__intro\">\r\n        We help our clients grow faster, operate smarter, and create lasting value through:\r\n      </p>\r\n    </div>\r\n\r\n    <!-- SERVICES -->\r\n    <div class=\"ab-services__grid\">\r\n      <div class=\"ab-service ab-reveal\">\r\n        <h3 class=\"ab-service__title\">Growth &amp; Strategy</h3>\r\n        <p class=\"ab-service__text\">\r\n          Driving revenue growth, market expansion, and competitive advantage.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-service ab-reveal\">\r\n        <h3 class=\"ab-service__title\">Shared Services &amp; Global Capability Centers (GCC)</h3>\r\n        <p class=\"ab-service__text\">\r\n          Designing and scaling efficient, high-performing hubs.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-service ab-reveal\">\r\n        <h3 class=\"ab-service__title\">Tech-Enabled Transformation</h3>\r\n        <p class=\"ab-service__text\">\r\n          Leveraging digital, automation, and analytics to reimagine operations.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-service ab-reveal\">\r\n        <h3 class=\"ab-service__title\">ESG &amp; Value Creation</h3>\r\n        <p class=\"ab-service__text\">\r\n          Embedding sustainability into business strategy for measurable impact.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-service ab-reveal\">\r\n        <h3 class=\"ab-service__title\">Business Process Advisory &amp; Industry 4.0</h3>\r\n        <p class=\"ab-service__text\">\r\n          Streamlining processes, boosting productivity, and enabling innovation.\r\n        </p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- ENABLERS -->\r\n    <div class=\"ab-enablers ab-reveal\">\r\n      <div class=\"ab-enablers__label\">Enablers</div>\r\n      <div class=\"ab-enablers__text\">\r\n        Our services are backed by proprietary technology assets, proven methodologies,\r\n        and a commitment to a trusted, secure, and compliant work environment—ensuring\r\n        data integrity and client confidentiality at all times.\r\n      </div>\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  // staggered reveal animation\r\n  window.addEventListener('load', ()=>{\r\n    document.querySelectorAll('#core-services .ab-reveal').forEach((el,i)=>{\r\n      setTimeout(()=> el.classList.add('is-in'), i*120);\r\n    });\r\n  });\r\n</script>\r\n\r\n<!-- ===================== ABOUT US — WHO WE ARE & CORE PRINCIPLES ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:#020C4F;\r\n    --c-indigo:#313B86;\r\n    --c-violet:#625AD8;\r\n    --c-pink:#FF4B8C;\r\n\r\n    --black:#0B0F1A;\r\n    --gray:#4B5168;\r\n    --line:rgba(49,59,134,0.16);\r\n    --white:#FFFFFF;\r\n  }\r\n\r\n  body{\r\n    margin:0;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:#fff;\r\n    color:var(--black);\r\n  }\r\n\r\n  .ab-who{\r\n    padding:100px 20px;\r\n    background:#fff;\r\n  }\r\n\r\n  .ab-who__inner{\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n  }\r\n\r\n  /* HEADER */\r\n  .ab-who__grid{\r\n    display:grid;\r\n    grid-template-columns:minmax(0,1.05fr) minmax(0,0.95fr);\r\n    gap:50px;\r\n    align-items:start;\r\n  }\r\n\r\n  .ab-who__eyebrow{\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:600;\r\n    margin-bottom:12px;\r\n  }\r\n\r\n  .ab-who__title{\r\n    font-size:clamp(30px,3.6vw,44px);\r\n    font-weight:700;\r\n    line-height:1.15;\r\n    color:var(--c-navy);\r\n    margin:0 0 18px;\r\n  }\r\n\r\n  .ab-who__text{\r\n    font-size:15.5px;\r\n    line-height:1.8;\r\n    color:var(--gray);\r\n    margin-bottom:16px;\r\n  }\r\n\r\n  /* IMAGE */\r\n  .ab-who__image{\r\n    border-radius:18px;\r\n    overflow:hidden;\r\n    border:1px solid var(--line);\r\n  }\r\n\r\n  .ab-who__image img{\r\n    width:100%;\r\n    height:auto;\r\n    display:block;\r\n  }\r\n\r\n  /* PRINCIPLES */\r\n  .ab-principles{\r\n    margin-top:80px;\r\n  }\r\n\r\n  .ab-principles__title{\r\n    font-size:clamp(26px,3.2vw,38px);\r\n    font-weight:700;\r\n    color:var(--c-navy);\r\n    margin-bottom:40px;\r\n  }\r\n\r\n  .ab-principle{\r\n    display:grid;\r\n    grid-template-columns:42px minmax(0,1fr);\r\n    gap:18px;\r\n    padding:26px 0;\r\n    border-top:1px solid var(--line);\r\n  }\r\n\r\n  .ab-principle:last-child{\r\n    border-bottom:1px solid var(--line);\r\n  }\r\n\r\n  .ab-principle__num{\r\n    font-size:14px;\r\n    font-weight:700;\r\n    color:var(--c-violet);\r\n  }\r\n\r\n  .ab-principle__content h4{\r\n    margin:0 0 8px;\r\n    font-size:17px;\r\n    font-weight:600;\r\n    color:var(--c-navy);\r\n  }\r\n\r\n  .ab-principle__content p{\r\n    margin:0 0 10px;\r\n    font-size:15px;\r\n    line-height:1.7;\r\n    color:#2E334D;\r\n  }\r\n\r\n  .ab-principle__impact{\r\n    font-size:14px;\r\n    line-height:1.7;\r\n    color:#3C4160;\r\n    padding-left:14px;\r\n    border-left:3px solid var(--c-pink);\r\n  }\r\n\r\n  /* REVEAL */\r\n  .ab-reveal{\r\n    opacity:0;\r\n    transform:translateY(16px);\r\n    transition:opacity .7s ease, transform .7s ease;\r\n  }\r\n  .ab-reveal.is-in{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n  }\r\n\r\n  @media (max-width:980px){\r\n    .ab-who{\r\n      padding:80px 18px;\r\n    }\r\n    .ab-who__grid{\r\n      grid-template-columns:1fr;\r\n      gap:36px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"ab-who\" id=\"who-we-are\">\r\n  <div class=\"ab-who__inner\">\r\n\r\n    <!-- WHO WE ARE -->\r\n    <div class=\"ab-who__grid ab-reveal\">\r\n      <div>\r\n        <div class=\"ab-who__eyebrow\">Who We Are</div>\r\n        <h2 class=\"ab-who__title\">A consulting partner built for lasting impact</h2>\r\n\r\n        <p class=\"ab-who__text\">\r\n          We are a consulting partner dedicated to driving growth, operational excellence,\r\n          technology enablement, and sustainability.\r\n        </p>\r\n\r\n        <p class=\"ab-who__text\">\r\n          Working as an extension of our clients’ teams, we support them from strategy to execution,\r\n          delivering results that are sustainable, measurable, and lasting.\r\n        </p>\r\n\r\n        <p class=\"ab-who__text\">\r\n          Our mission is clear: make our clients successful and earn the privilege of being their Advisor for Life.\r\n        </p>\r\n\r\n        <p class=\"ab-who__text\">\r\n          By combining global talent, deep domain expertise, and proprietary technology assets,\r\n          we deliver transformations that accelerate growth, strengthen resilience, and spark innovation.\r\n        </p>\r\n\r\n        <p class=\"ab-who__text\">\r\n          We operate in a trusted, secure, and compliant environment, ensuring confidentiality,\r\n          data integrity, and uncompromising quality in everything we do.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"ab-who__image\">\r\n        <img src=\"https://mediumpurple-ant-531485.hostingersite.com/wp-content/uploads/2025/12/Picture1.png\" alt=\"Who We Are\">\r\n      </div>\r\n    </div>\r\n\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  // reveal animation\r\n  window.addEventListener('load', ()=>{\r\n    document.querySelectorAll('.ab-reveal').forEach((el,i)=>{\r\n      setTimeout(()=> el.classList.add('is-in'), i*140);\r\n    });\r\n  });\r\n</script>\r\n\r\n<!-- ============ 5 CORE PRINCIPLES — OPTION B (LEFT SELECTOR + DETAIL PANEL, NO BACKGROUND) ============ -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />\r\n\r\n<style>\r\n  :root{\r\n    --c-navy:#020C4F;\r\n    --c-indigo:#313B86;\r\n    --c-violet:#625AD8;\r\n    --c-pink:#FF4B8C;\r\n\r\n    --black:#0B0F1A;\r\n    --gray:#4B5168;\r\n    --muted:#2E334D;\r\n    --line:rgba(49,59,134,0.16);\r\n    --soft:rgba(2,12,79,0.04);\r\n    --white:#FFFFFF;\r\n  }\r\n\r\n  body{\r\n    margin:0;\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:#fff;\r\n    color:var(--black);\r\n  }\r\n\r\n  .cpB{\r\n    padding:78px 20px;\r\n      /* ✅ PREMIUM EXECUTIVE BACKGROUND */\r\n    background:\r\n      radial-gradient(circle at 15% 0%, rgba(98,90,216,.08), transparent 55%),\r\n      radial-gradient(circle at 90% 25%, rgba(31,156,228,.08), transparent 55%),\r\n      radial-gradient(circle at 70% 110%, rgba(2,12,79,.06), transparent 60%),\r\n      rgba(49,59,134,.03);\r\n  \r\n  }\r\n  .cpB__inner{\r\n    max-width:1200px;\r\n    margin:0 auto;\r\n  }\r\n\r\n  .cpB__title{\r\n    margin:0 0 18px;\r\n    font-size:clamp(26px,3vw,38px);\r\n    line-height:1.2;\r\n    font-weight:700;\r\n    color:var(--c-navy);\r\n  }\r\n\r\n  .cpB__wrap{\r\n    display:grid;\r\n    grid-template-columns: minmax(0, 0.44fr) minmax(0, 0.56fr);\r\n    gap:26px;\r\n    align-items:start;\r\n  }\r\n\r\n  /* LEFT SELECTOR */\r\n  .cpB__rail{\r\n    border:1px solid var(--line);\r\n    border-radius:18px;\r\n    overflow:hidden;\r\n    background:#fff;\r\n  }\r\n\r\n  .cpB__item{\r\n    width:100%;\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:space-between;\r\n    gap:12px;\r\n    padding:16px 16px;\r\n    background:#fff;\r\n    border:0;\r\n    border-top:1px solid var(--line);\r\n    cursor:pointer;\r\n    text-align:left;\r\n    transition:background .22s ease;\r\n  }\r\n  .cpB__item:first-child{border-top:none;}\r\n\r\n  .cpB__item:hover{\r\n    background:rgba(2,12,79,0.02);\r\n  }\r\n\r\n  .cpB__left{\r\n    display:flex;\r\n    align-items:center;\r\n    gap:12px;\r\n    min-width:0;\r\n  }\r\n\r\n  .cpB__num{\r\n    width:38px;height:38px;\r\n    border-radius:14px;\r\n    display:grid;\r\n    place-items:center;\r\n    border:1px solid var(--line);\r\n    color:var(--c-violet);\r\n    font-weight:800;\r\n    flex:0 0 auto;\r\n    background:#fff;\r\n  }\r\n\r\n  .cpB__label{\r\n    margin:0;\r\n    font-size:14px;\r\n    font-weight:650;\r\n    color:var(--c-navy);\r\n    white-space:nowrap;\r\n    overflow:hidden;\r\n    text-overflow:ellipsis;\r\n  }\r\n\r\n  .cpB__hint{\r\n    width:34px;height:34px;\r\n    border-radius:12px;\r\n    border:1px solid var(--line);\r\n    display:grid;\r\n    place-items:center;\r\n    color:var(--c-indigo);\r\n    background:#fff;\r\n    transition:transform .22s ease, background .22s ease, border-color .22s ease;\r\n    flex:0 0 auto;\r\n  }\r\n\r\n\r\n\r\n  /* Active state */\r\n  .cpB__item[aria-selected=\"true\"]{\r\n    background:rgba(2,12,79,0.03);\r\n  }\r\n  .cpB__item[aria-selected=\"true\"] .cpB__num{\r\n    border-color:rgba(255,75,140,0.35);\r\n    box-shadow:0 10px 24px rgba(0,0,0,0.06);\r\n  }\r\n  .cpB__item[aria-selected=\"true\"] .cpB__hint{\r\n    border-color:rgba(255,75,140,0.28);\r\n    background:rgba(255,75,140,0.06);\r\n    transform:translateX(1px);\r\n  }\r\n\r\n  /* RIGHT DETAIL PANEL */\r\n  .cpB__panel{\r\n    border:1px solid var(--line);\r\n    border-radius:18px;\r\n    background:#fff;\r\n    padding:18px 18px 16px;\r\n    box-shadow:0 18px 40px rgba(0,0,0,0.06);\r\n    position:sticky;\r\n    top:18px;\r\n    display: flex;\r\n    height: 100%;\r\n  }\r\n\r\n  .cpB__panelTop{\r\n    display:flex;\r\n    align-items:flex-start;\r\n    justify-content:space-between;\r\n    gap:14px;\r\n    padding-bottom:14px;\r\n    border-bottom:1px solid var(--line);\r\n    margin-bottom:14px;\r\n  }\r\n\r\n  .cpB__panelTitleWrap{\r\n    min-width:0;\r\n  }\r\n\r\n  .cpB__panelKicker{\r\n    margin:0 0 6px;\r\n    font-size:12px;\r\n    letter-spacing:.16em;\r\n    text-transform:uppercase;\r\n    color:var(--c-indigo);\r\n    font-weight:700;\r\n  }\r\n\r\n  .cpB__panelTitle{\r\n    margin:0;\r\n    font-size:20px;\r\n    line-height:1.25;\r\n    color:var(--c-navy);\r\n    font-weight:750;\r\n  }\r\n\r\n  .cpB__badge{\r\n    flex:0 0 auto;\r\n    height:34px;\r\n    padding:0 12px;\r\n    border-radius:999px;\r\n    border:1px solid var(--line);\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:8px;\r\n    color:var(--c-navy);\r\n    font-size:13px;\r\n    font-weight:700;\r\n    background:#fff;\r\n  }\r\n  .cpB__badgeDot{\r\n    width:8px;height:8px;border-radius:999px;\r\n    background:linear-gradient(135deg,var(--c-pink),var(--c-violet));\r\n  }\r\n\r\n  .cpB__desc{\r\n    margin:0 0 12px;\r\n    font-size:15px;\r\n    line-height:1.75;\r\n    color:var(--muted);\r\n  }\r\n\r\n  .cpB__impact{\r\n    margin:0;\r\n    font-size:14.5px;\r\n    line-height:1.7;\r\n    color:#3C4160;\r\n    padding-left:14px;\r\n    border-left:3px solid var(--c-pink);\r\n  }\r\n\r\n  /* subtle crossfade on change */\r\n  .cpB__fade{\r\n    opacity:1;\r\n    transform:translateY(0);\r\n    transition:opacity .18s ease, transform .18s ease;\r\n  }\r\n  .cpB__fade.is-switching{\r\n    opacity:0;\r\n    transform:translateY(6px);\r\n  }\r\n\r\n  /* Mobile */\r\n  @media (max-width:980px){\r\n    .cpB{padding:68px 18px;}\r\n    .cpB__wrap{grid-template-columns:1fr; gap:16px;}\r\n    .cpB__panel{position:relative; top:auto;}\r\n    .cpB__label{white-space:normal; overflow:visible; text-overflow:unset;}\r\n  }\r\n  \r\n  \r\n</style>\r\n\r\n<section class=\"cpB\" id=\"core-principles\">\r\n  <div class=\"cpB__inner\">\r\n    <h3 class=\"cpB__title\">Our 5 Core Principles — and the Impact We Deliver</h3>\r\n\r\n    <div class=\"cpB__wrap\">\r\n      <!-- LEFT SELECTOR -->\r\n      <div class=\"cpB__rail\" role=\"tablist\" aria-label=\"Core principles selector\">\r\n        <button class=\"cpB__item\" role=\"tab\" aria-selected=\"true\" data-key=\"p1\">\r\n          <div class=\"cpB__left\">\r\n            <div class=\"cpB__num\">01</div>\r\n            <p class=\"cpB__label\">Client-First Mindset</p>\r\n          </div>\r\n          <div class=\"cpB__hint\" aria-hidden=\"true\">→</div>\r\n        </button>\r\n\r\n        <button class=\"cpB__item\" role=\"tab\" aria-selected=\"false\" data-key=\"p2\">\r\n          <div class=\"cpB__left\">\r\n            <div class=\"cpB__num\">02</div>\r\n            <p class=\"cpB__label\">Employee Engagement &amp; Ownership</p>\r\n          </div>\r\n          <div class=\"cpB__hint\" aria-hidden=\"true\">→</div>\r\n        </button>\r\n\r\n        <button class=\"cpB__item\" role=\"tab\" aria-selected=\"false\" data-key=\"p3\">\r\n          <div class=\"cpB__left\">\r\n            <div class=\"cpB__num\">03</div>\r\n            <p class=\"cpB__label\">Ownership for Excellence</p>\r\n          </div>\r\n          <div class=\"cpB__hint\" aria-hidden=\"true\">→</div>\r\n        </button>\r\n\r\n        <button class=\"cpB__item\" role=\"tab\" aria-selected=\"false\" data-key=\"p4\">\r\n          <div class=\"cpB__left\">\r\n            <div class=\"cpB__num\">04</div>\r\n            <p class=\"cpB__label\">Deliver Sustainable Results</p>\r\n          </div>\r\n          <div class=\"cpB__hint\" aria-hidden=\"true\">→</div>\r\n        </button>\r\n\r\n        <button class=\"cpB__item\" role=\"tab\" aria-selected=\"false\" data-key=\"p5\">\r\n          <div class=\"cpB__left\">\r\n            <div class=\"cpB__num\">05</div>\r\n            <p class=\"cpB__label\">Ensure Positive ROI</p>\r\n          </div>\r\n          <div class=\"cpB__hint\" aria-hidden=\"true\">→</div>\r\n        </button>\r\n      </div>\r\n\r\n      <!-- RIGHT DETAIL PANEL -->\r\n      <aside class=\"cpB__panel\" role=\"tabpanel\" aria-live=\"polite\">\r\n        <div class=\"cpB__fade\" id=\"cpB-fade\">\r\n          <div class=\"cpB__panelTop\">\r\n            <div class=\"cpB__panelTitleWrap\">\r\n              <p class=\"cpB__panelKicker\">Core Principle</p>\r\n              <h4 class=\"cpB__panelTitle\" id=\"cpB-title\">Client-First Mindset</h4>\r\n            </div>\r\n            <div class=\"cpB__badge\"><span class=\"cpB__badgeDot\" aria-hidden=\"true\"></span><span id=\"cpB-badge\">01</span></div>\r\n          </div>\r\n\r\n          <p class=\"cpB__desc\" id=\"cpB-desc\">\r\n            We put your priorities at the center of everything we do, aligning strategies with your vision.\r\n          </p>\r\n\r\n          <p class=\"cpB__impact\" id=\"cpB-impact\">\r\n            Measurable Impact: 95%+ client satisfaction scores, repeat engagements with over 80% of our clients, and measurable business KPI improvements within the first 3–6 months.\r\n          </p>\r\n        </div>\r\n      </aside>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<script>\r\n  (function(){\r\n    const data = {\r\n      p1:{\r\n        num:\"01\",\r\n        title:\"Client-First Mindset\",\r\n        desc:\"We put your priorities at the center of everything we do, aligning strategies with your vision.\",\r\n        impact:\"Measurable Impact: 95%+ client satisfaction scores, repeat engagements with over 80% of our clients, and measurable business KPI improvements within the first 3–6 months.\"\r\n      },\r\n      p2:{\r\n        num:\"02\",\r\n        title:\"Employee Engagement & Ownership\",\r\n        desc:\"We empower our people to take responsibility, innovate, and drive impact as if they own the outcome.\",\r\n        impact:\"Measurable Impact: 90%+ project ownership scores in internal reviews, faster decision cycles, and proactive issue resolution before escalation in 95% of cases.\"\r\n      },\r\n      p3:{\r\n        num:\"03\",\r\n        title:\"Ownership for Excellence\",\r\n        desc:\"We hold ourselves accountable for delivering at the highest standards — every time, without compromise.\",\r\n        impact:\"Measurable Impact: Zero critical defects in deliverables, >98% on-time project delivery, and client-rated quality score of 9/10 or higher.\"\r\n      },\r\n      p4:{\r\n        num:\"04\",\r\n        title:\"Deliver Sustainable Results\",\r\n        desc:\"We design strategies and solutions that deliver measurable, long-term value beyond the initial engagement.\",\r\n        impact:\"Measurable Impact: Minimum 12-month sustainability check on implemented solutions, with over 85% of outcomes still delivering value a year later.\"\r\n      },\r\n      p5:{\r\n        num:\"05\",\r\n        title:\"Ensure Positive ROI\",\r\n        desc:\"We commit to delivering financial and operational returns that far exceed investment.\",\r\n        impact:\"Measurable Impact: Positive ROI within 16 weeks in all engagements; target 4:1 ROI following full-scale rollout.\"\r\n      }\r\n    };\r\n\r\n    const tabs = Array.from(document.querySelectorAll('#core-principles .cpB__item'));\r\n    const fade = document.getElementById('cpB-fade');\r\n    const title = document.getElementById('cpB-title');\r\n    const badge = document.getElementById('cpB-badge');\r\n    const desc = document.getElementById('cpB-desc');\r\n    const impact = document.getElementById('cpB-impact');\r\n\r\n    function setActive(btn){\r\n      const key = btn.getAttribute('data-key');\r\n      const d = data[key];\r\n      if(!d) return;\r\n\r\n      tabs.forEach(t => t.setAttribute('aria-selected', t === btn ? 'true' : 'false'));\r\n\r\n      // subtle crossfade\r\n      fade.classList.add('is-switching');\r\n      setTimeout(()=>{\r\n        badge.textContent = d.num;\r\n        title.textContent = d.title;\r\n        desc.textContent = d.desc;\r\n        impact.textContent = d.impact;\r\n        fade.classList.remove('is-switching');\r\n      }, 160);\r\n    }\r\n\r\n    tabs.forEach(btn=>{\r\n      btn.addEventListener('click', ()=> setActive(btn));\r\n      btn.addEventListener('keydown', (e)=>{\r\n        const i = tabs.indexOf(btn);\r\n        if(e.key === 'ArrowDown' || e.key === 'ArrowRight'){\r\n          e.preventDefault();\r\n          const next = tabs[i+1] || tabs[0];\r\n          next.focus(); setActive(next);\r\n        }\r\n        if(e.key === 'ArrowUp' || e.key === 'ArrowLeft'){\r\n          e.preventDefault();\r\n          const prev = tabs[i-1] || tabs[tabs.length-1];\r\n          prev.focus(); setActive(prev);\r\n        }\r\n      });\r\n    });\r\n  })();\r\n</script>";
